#!/usr/bin/env python3
"""Build Michel's Life v3.0.202 frontend from the canonical bootstrap source.

The UI fixes in this builder are applied directly to the core function definitions
that ship in index.html. It does not append runtime hotfix or developer overlays.
"""
from __future__ import annotations
import argparse
import html as html_lib
import json
import re
from pathlib import Path

VERSION = "3.0.202"
LOGO_DATA = "data:image/png;base64,"
AVATAR_DATA = "data:image/jpeg;base64,"

CORE_STYLE = r'''<style id="mlv-v30202-core-branding-style">
#v30171Sidebar .v30171-brand-mark{width:82px!important;height:82px!important;border-radius:0!important;padding:0!important;background:transparent!important;border:0!important;box-shadow:none!important;overflow:visible!important}
#v30171Sidebar .v30171-brand-mark img{width:82px!important;height:82px!important;display:block!important;object-fit:contain!important;filter:drop-shadow(0 8px 18px rgba(0,0,0,.28))}
#v30171Sidebar .v30171-brand-copy{min-width:0}
.mlvdev-card{position:relative;overflow:hidden;padding:20px!important}
.mlvdev-main{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px;align-items:stretch}
.mlvdev-avatar-wrap{position:relative;min-width:0}
.mlvdev-avatar{width:220px;height:270px;border-radius:24px;object-fit:cover;object-position:center 68%;display:block;border:2px solid rgba(231,187,92,.58);box-shadow:0 16px 36px rgba(0,0,0,.32)}
.mlvdev-info{min-width:0;display:flex;flex-direction:column;justify-content:center}
.mlvdev-title h2{margin:0;font-size:24px;line-height:1.05}.mlvdev-title p{margin:6px 0 0;color:var(--muted);font-size:11px;line-height:1.4}
.mlvdev-copy{margin-top:15px;color:var(--muted);font-size:10.5px;line-height:1.6;max-width:720px}
.mlvdev-contact{margin-top:11px;font-size:10px;color:var(--muted)}.mlvdev-contact a{color:inherit;text-decoration:none;border-bottom:1px dotted rgba(255,255,255,.22)}
.mlvdev-socials{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:16px;max-width:660px}
.mlvdev-social{min-height:58px;border-radius:13px;display:flex;align-items:center;padding:9px 12px;text-decoration:none;color:inherit;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.025);transition:transform .15s ease,border-color .15s ease,background .15s ease}
.mlvdev-social:hover{transform:translateY(-2px);border-color:rgba(231,187,92,.42);background:rgba(231,187,92,.07)}.mlvdev-social strong{font-size:10.5px}.mlvdev-social small{display:block;margin-top:2px;font-size:8px;color:var(--muted);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mlvdev-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:14px}.mlvdev-meta>div{padding:9px 10px;border-radius:11px;border:1px solid rgba(255,255,255,.07);background:rgba(0,0,0,.08)}.mlvdev-meta small{display:block;color:var(--muted);font-size:7.5px;font-weight:800;letter-spacing:.06em}.mlvdev-meta b{display:block;margin-top:2px;font-size:9.5px}
.mlvdev-legal{margin-top:14px;padding-top:10px;border-top:1px solid rgba(255,255,255,.055);font-size:8.2px;line-height:1.45;color:rgba(255,255,255,.48)}.mlvdev-copyright{display:block;margin-top:6px;font-size:7.8px;color:rgba(255,255,255,.42)}
.mlv-toast-unified .mlv197-toast-close{display:flex!important}
@media(max-width:1050px){.mlvdev-main{grid-template-columns:180px minmax(0,1fr);gap:18px}.mlvdev-avatar{width:180px;height:225px}.mlvdev-socials{grid-template-columns:1fr 1fr}}
@media(max-width:760px){.mlvdev-main{grid-template-columns:1fr}.mlvdev-avatar{width:min(100%,320px);height:360px}.mlvdev-socials,.mlvdev-meta{grid-template-columns:1fr}}
</style>'''


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one source match, found {count}")
    return text.replace(old, new, 1)


def remove_obsolete_overlay(text: str, marker: str) -> str:
    # Remove an old style/script block by id if a previously generated bundle is reused.
    pattern = rf'<(style|script)\b[^>]*id=["\']{re.escape(marker)}["\'][^>]*>.*?</\1>'
    return re.sub(pattern, '', text, flags=re.I | re.S)


def esc(v: object) -> str:
    return html_lib.escape(str(v or ''), quote=True)


def developer_html(profile: dict) -> str:
    developer = esc(profile['developer'])
    studio = esc(profile['studio'])
    email = esc(profile['email'])
    copyright_text = esc(profile['copyright'])
    socials = [
        ('Instagram', profile['instagram'], '@realmichelduarte'),
        ('Facebook', profile['facebook'], 'realmichelduarte'),
        ('LinkedIn', profile['linkedin'], 'realmichelduart'),
        ('GitHub', profile['github'], 'realmichelduarte'),
        ('Email', 'mailto:' + profile['email'], profile['email']),
    ]
    links = ''.join(
        f'<a class="mlvdev-social" href="{esc(url)}" target="_blank" rel="noopener noreferrer"><span><strong>{esc(name)}</strong><small>{esc(handle)}</small></span></a>'
        for name, url, handle in socials
    )
    return (
        '<section class="card mlvdev-card" data-mlv-about-core data-mlv-developer><div class="mlvdev-main">'
        '<div class="mlvdev-avatar-wrap">'
        f'<img class="mlvdev-avatar" src="assets/michel_duarte_avatar.jpg" alt="{developer}"></div>'
        '<div class="mlvdev-info"><div class="mlvdev-title">'
        f'<h2>{developer}</h2><p>Developer · {studio}</p></div>'
        f'<div class="mlvdev-copy">Michel’s Life is created and maintained by {developer} under {studio}. Independent software focused on productivity, life systems and personal tools.</div>'
        f'<div class="mlvdev-contact">Contact: <a href="mailto:{email}">{email}</a></div>'
        f'<div class="mlvdev-socials">{links}</div>'
        '<div class="mlvdev-meta"><div><small>APP</small><b>Michel’s Life</b></div><div><small>VERSION</small><b>v3.0.202</b></div><div><small>LICENSE</small><b>Proprietary · Personal use</b></div></div>'
        '<div class="mlvdev-legal">Free for personal use. Unauthorized copying, modification, redistribution, rebranding, resale, sublicensing, or claiming this software as your own is not permitted without prior written permission.'
        f'<span class="mlvdev-copyright">{copyright_text}</span></div></div></div></section>'
    )


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument('--index', required=True)
    ap.add_argument('--profile', required=True)
    ap.add_argument('--release-overlay')
    args = ap.parse_args()

    path = Path(args.index)
    text = path.read_text(encoding='utf-8')
    profile = json.loads(Path(args.profile).read_text(encoding='utf-8'))

    # If the bootstrap is still 3.0.201, bring in the 3.0.202 feature module once.
    if 'mlv-v30202-release-readiness-script' not in text:
        if not args.release_overlay:
            raise SystemExit('3.0.202 release-readiness module is missing and --release-overlay was not provided.')
        overlay = Path(args.release_overlay).read_text(encoding='utf-8')
        if 'mlv-v30202-release-readiness-script' not in overlay:
            raise SystemExit('Invalid v3.0.202 release-readiness module.')
        old_account = "function specificAccount(v){const s=norm(v);if(s.includes('micheltheog'))return'micheltheog';if(s.includes('realmichelduarte'))return'realmichelduarte';return'';}"
        new_account = "function specificAccount(v){const raw=String(v||'');const s=norm(raw);if(!/instagram|followers|following|unfollow/.test(s))return'';const at=raw.match(/@([a-z0-9._]{2,30})/i);if(at)return at[1].toLowerCase();const paren=raw.match(/\(([a-z0-9._]{2,30})\)/i);if(paren)return paren[1].toLowerCase();const labeled=raw.match(/(?:account|cuenta)\s*[:\-]?\s*([a-z0-9._]{2,30})/i);return labeled?labeled[1].toLowerCase():'';}"
        if old_account not in text:
            raise SystemExit('Expected legacy account matcher not found in the 3.0.201 bootstrap.')
        text = text.replace('3.0.201', VERSION).replace(old_account, new_account, 1)
        pos = text.lower().rfind('</body>')
        if pos < 0:
            raise SystemExit('index.html closing </body> tag not found')
        text = text[:pos] + '\n' + overlay + '\n' + text[pos:]

    # Old repair layers must never survive into the final frontend.
    for marker in (
        'mlv-developer-branding-style', 'mlv-developer-branding',
        'mlv-v30202-ui-hotfix-style', 'mlv-v30202-ui-hotfix-script',
    ):
        text = remove_obsolete_overlay(text, marker)

    # Put the permanent visual rules in the document source itself.
    text = remove_obsolete_overlay(text, 'mlv-v30202-core-branding-style')
    head = text.lower().rfind('</head>')
    if head < 0:
        raise SystemExit('index.html closing </head> tag not found')
    text = text[:head] + '\n' + CORE_STYLE + '\n' + text[head:]

    # Settings description: this pane is now developer/license content, not a placeholder.
    text = re.sub(
        r"\['about','ⓘ','About','[^']*'\]",
        "['about','ⓘ','About','Developer, license and build information.']",
        text,
        count=1,
    )

    # Root sidebar rendering: no monogram fallback as the normal output.
    old_sidebar = "side.innerHTML='<div class=\"brand v30171-brand\"><div class=\"brand-mark v30171-brand-mark\" aria-hidden=\"true\">M</div><div><h1 class=\"v30171-brand-title\" style=\"color:var(--ui-gold,var(--gold,#ffd166))!important\">MICHEL\\'S LIFE</h1><p class=\"v30171-brand-sub\">Personal Progress System</p></div></div><nav id=\"v30171PrimaryNav\" class=\"v30171-primary-nav\"></nav>';"
    new_sidebar = "side.innerHTML='<div class=\"brand v30171-brand\"><div class=\"brand-mark v30171-brand-mark\" aria-hidden=\"true\"><img src=\"assets/michels_life_mark.png\" alt=\"\"></div><div class=\"v30171-brand-copy\"><h1 class=\"v30171-brand-title\" style=\"color:var(--ui-gold,var(--gold,#ffd166))!important\">MICHEL\\'S LIFE</h1><p class=\"v30171-brand-sub\">Personal Progress System</p></div></div><nav id=\"v30171PrimaryNav\" class=\"v30171-primary-nav\"></nav>';"
    if old_sidebar in text:
        text = replace_once(text, old_sidebar, new_sidebar, 'sidebar creation')
    elif 'assets/michels_life_mark.png' not in text:
        raise SystemExit('Sidebar creation source not found.')

    old_brand_sync = "const brand=side.querySelector('.brand');if(brand){const h=brand.querySelector('h1'),p=brand.querySelector('p');if(h)h.textContent=\"MICHEL'S LIFE\";if(p)p.textContent='Personal Progress System';}"
    new_brand_sync = "const brand=side.querySelector('.brand');if(brand){const h=brand.querySelector('h1'),p=brand.querySelector('p'),mark=brand.querySelector('.v30171-brand-mark');if(h)h.textContent=\"MICHEL'S LIFE\";if(p)p.textContent='Personal Progress System';if(mark&&!mark.querySelector('img'))mark.innerHTML='<img src=\"assets/michels_life_mark.png\" alt=\"\">';brand.querySelectorAll('.v30171-brand-legal').forEach(x=>x.remove())}"
    if old_brand_sync in text:
        text = replace_once(text, old_brand_sync, new_brand_sync, 'sidebar sync')

    # Replace the actual About pane function, not a post-render overlay.
    about_pattern = r"function aboutPane\(\)\{return .*?\}\nfunction moveDataActions\(panes\)\{"
    about_replacement = "function aboutPane(){return `" + developer_html(profile).replace('`', '\\`') + "`}\nfunction moveDataActions(panes){"
    text, about_count = re.subn(about_pattern, lambda _m: about_replacement, text, count=1, flags=re.S)
    if about_count != 1:
        raise SystemExit(f'aboutPane core replacement: expected 1 match, found {about_count}')

    # Insert About content when Settings is built. This fixes the original empty pane cause.
    panes_anchor = "const panes={};content.querySelectorAll('[data-v30171-pane]').forEach(p=>panes[p.dataset.v30171Pane]=p);"
    about_line = "if(panes.about&&!panes.about.querySelector('[data-mlv-about-core]'))panes.about.insertAdjacentHTML('beforeend',aboutPane());"
    inserts=[]
    if about_line not in text: inserts.append(about_line)
    if inserts:
        text = replace_once(text, panes_anchor, panes_anchor + '\n   ' + '\n   '.join(inserts), 'Settings pane core mounts')

    classify_anchor = "function classify(el){\n if(el?.matches?.('[data-mlv190-google-card]'))return 'google';"
    classify_rule = " if(el?.matches?.('[data-mlv-developer],[data-mlv200-update],[data-mlv202-update],[data-mlv202-changelog]'))return 'about';"
    if classify_rule not in text:
        text = replace_once(text, classify_anchor, classify_anchor + '\n' + classify_rule, 'About ownership in Settings classifier')

    # Replace the original app toast at its source so early Google errors and later
    # reliability errors use one deduplicated, dismissible notification system.
    core_toast_pattern = r"function toast\(title,msg='',kind=''\)\{.*?\}\nfunction escapeHtml\(s\)"
    core_toast = r"""function toast(title,msg='',kind='',opts={}){
  const wrap=$('#toastWrap');if(!wrap)return null;
  const text=(String(title)+' '+String(msg)).toLowerCase();
  const error=kind==='error'||/(error|failed|could not|needs attention|invalid)/i.test(text);
  const persistent=opts.persistent===true||error||/(conflict|warning)/i.test(text);
  const session=window.__mlvToastSession||(window.__mlvToastSession={dismissed:new Set(),active:new Map()});
  const key=(error?String(msg||title):(String(title||'')+'\n'+String(msg||''))).trim().toLowerCase();
  if(session.dismissed.has(key))return null;
  const existing=session.active.get(key);if(existing?.isConnected)return existing;
  [...wrap.querySelectorAll('.toast')].forEach(old=>{const oldMsg=old.querySelector('span')?.textContent||'';if(error&&String(oldMsg).trim().toLowerCase()===String(msg||'').trim().toLowerCase())old.remove()});
  const div=document.createElement('div');div.className='toast mlv-toast-unified'+(error?' mlv197-toast-error':'');div.dataset.mlvToastKey=key;
  div.innerHTML='<button class=\"mlv197-toast-close\" type=\"button\" aria-label=\"Dismiss\">×</button><b>'+escapeHtml(title)+'</b><span>'+escapeHtml(msg)+'</span>';
  session.active.set(key,div);
  const remove=(dismiss=false)=>{if(dismiss)session.dismissed.add(key);if(session.active.get(key)===div)session.active.delete(key);div.remove()};
  div.querySelector('.mlv197-toast-close').addEventListener('click',e=>{e.preventDefault();e.stopPropagation();remove(true)});
  wrap.appendChild(div);
  if(!persistent)setTimeout(()=>{if(!div.isConnected)return;div.style.opacity='0';div.style.transform='translateY(10px)';setTimeout(()=>remove(false),300)},4200);
  return div;
}
function escapeHtml(s)"""
    text, core_toast_count = re.subn(core_toast_pattern, lambda _m: core_toast, text, count=1, flags=re.S)
    if core_toast_count != 1:
        raise SystemExit(f'root toast replacement: expected 1 match, found {core_toast_count}')

    # Reliability notifications delegate to the root toast so Google and Cloud cannot
    # create a second copy of the same error through a parallel notification system.
    notification_pattern = r"function legacyWrap\(\)\{return document\.getElementById\('toastWrap'\)\}\n(?:const dismissedNotifications=.*?\n)?(?:const activeNotifications=.*?\n)?(?:function notificationKey.*?\n)?function notification\(title,msg='',opts=\{\}\)\{.*?\n\}\nwindow\.toast=function\(title,msg='',kind=''\)\{return notification\(title,msg,\{kind\}\)\};"
    notification_core = "function legacyWrap(){return document.getElementById('toastWrap')}\nfunction notification(title,msg='',opts={}){return toast(title,msg,opts.kind||'',opts)}"
    text, notif_count = re.subn(notification_pattern, lambda _m: notification_core, text, count=1, flags=re.S)
    if notif_count != 1:
        raise SystemExit(f'notification delegation: expected 1 match, found {notif_count}')

    # Chapter Scene cards must call the existing ChapterScenes selector.
    old_scene = "const scene=e.target?.closest?.('.v30171-scene-card[data-v30170-scene]');if(scene)setTimeout(()=>refreshChapterSelection(document.getElementById('tab-settings')),40);"
    new_scene = "const scene=e.target?.closest?.('.v30171-scene-card[data-v30170-scene]');if(scene){e.preventDefault();const ok=window.ChapterScenesV30170?.select?.(scene.dataset.v30170Scene);if(ok!==false)setTimeout(()=>refreshChapterSelection(document.getElementById('tab-settings')),40);return}"
    if old_scene in text:
        text = replace_once(text, old_scene, new_scene, 'Chapter Scene selection handler')
    elif new_scene not in text:
        raise SystemExit('Chapter Scene click handler not found.')

    # Make Open Story deterministic from the Current Chapter hero.
    old_chapter_click = "document.addEventListener('click',function(e){if(e.target&&e.target.closest&&e.target.closest('[data-tab],#v131More'))setTimeout(maintain,40)},true);"
    new_chapter_click = "document.addEventListener('click',function(e){const story=e.target&&e.target.closest&&e.target.closest('.v30165-hero-actions [data-tab=\"story\"]');if(story){e.preventDefault();e.stopPropagation();try{state.activeTab='story';if(typeof save==='function')save();if(typeof renderAll==='function')renderAll()}catch(_){}setTimeout(maintain,40);return}if(e.target&&e.target.closest&&e.target.closest('[data-tab],#v131More'))setTimeout(maintain,40)},true);"
    if old_chapter_click in text:
        text = replace_once(text, old_chapter_click, new_chapter_click, 'Current Chapter Open Story handler')
    elif new_chapter_click not in text:
        raise SystemExit('Current Chapter click handler not found.')

    # Embed branding assets after all HTML replacements so the final document is self-contained.
    text = text.replace('assets/michels_life_mark.png', LOGO_DATA).replace('assets/michel_duarte_avatar.jpg', AVATAR_DATA)

    # Final invariants: the generated file itself owns the behavior.
    required = (
        'data:image/png;base64,',
        'v30171-brand-legal',
        "panes.about.insertAdjacentHTML('beforeend',aboutPane())",
        'data-mlv-about-core',
        'data-mlv-developer',
        'data:image/jpeg;base64,',
        profile['copyright'],
        'window.__mlvToastSession',
        'ChapterScenesV30170?.select?.(scene.dataset.v30170Scene)',
        '.v30165-hero-actions [data-tab=\"story\"]',
    )
    for value in required:
        if value not in text:
            raise SystemExit(f'Generated frontend missing required core value: {value}')
    for forbidden in ('mlv-v30202-ui-hotfix-script', 'id="mlv-developer-branding"'):
        if forbidden in text:
            raise SystemExit(f'Obsolete runtime repair remains in frontend: {forbidden}')

    path.write_text(text, encoding='utf-8')
    print('Built v3.0.202 core frontend: About, branding, legal and notification behavior are in the source.')


if __name__ == '__main__':
    main()